  await page.evaluate(()=>NAGWEB_MOTION_LAB.open());await page.click('[data-motion-template="ticker-loop"]');await ready();assert.equal(await page.$eval('[data-motion-config="duration"]',n=>n.value),'12');assert.equal(await page.$eval('[data-motion-stream-count]',n=>[n.min,n.max].join(',')),'4,24');assert.equal(await page.$eval('[data-motion-stream="zoom"]',n=>n.value),'45');assert.equal(await page.$eval('[data-motion-stream="backgroundType"]',n=>n.value),'none');assert.equal(await page.$eval('[data-motion-stream="cardRatio"]',n=>n.value),'1:1');assert.equal(await page.$eval('[data-motion-stream="angle"]',n=>n.value),'-6');assert.equal(await page.$eval('[data-motion-stream="movement"]',n=>n.value),'continuous');assert.equal(await page.$eval('[data-motion-stream="orientation"]',n=>n.value),'horizontal');assert.equal(await page.$eval('[data-stream-loop-pulse]',n=>n.hidden),true);assert.equal(await page.$eval('[data-stream-waypoints]',n=>n.hidden),true);assert.equal(await page.$eval('[data-stream-loop-pause]',n=>n.hidden),true);
