  async function stableTextures(expectCap=false){const result=await page.$eval('.nw-motion-dialog iframe',f=>{const d=f.contentDocument,rt=f.contentWindow.__NAG_SCROLL_DIRECTOR[d.querySelector('.sc').dataset.id],native=d.createElement;let created=0;const canvases=[];d.createElement=function(tag,...args){const n=native.call(this,tag,...args);if(tag==='canvas'){created++;canvases.push(n);}return n;};try{for(let i=0;i<60;i++)rt.set(i/60);const warm=created;created=0;for(let i=0;i<60;i++)rt.set(i/60);return{warm,after:created,max:Math.max(0,...canvases.map(n=>Math.max(n.width,n.height)))};}finally{d.createElement=native;}});assert.ok(result.warm<=12);assert.equal(result.after,0,'Animating zoom retains the image textures');assert.ok(result.max<=2048,'Large zoom textures stay bounded');if(expectCap)assert.equal(result.max,2048,'The large portrait zoom exercises the texture cap');}
